INSERT INTO `product_detail` (`id`, `productCode`, `name`, `price`, `description`, `category`, `stock`, `image_url`, `created_at`) VALUES (10, '564974', 'Nhẫn bạc nữ đính kim cương Moissanite Elfleda LILI_564974', '2321000', 'Chiếc nhẫn cao cấp được làm từ bạc S925 đính viên kim cương Moissanite 1 carat. Nó sẽ mang đến cho bạn sự sang trọng và quý phái. Dù trong hoàn cảnh nào: đi làm, đi dự tiệc hay đi chơi với bạn bè, đôi tay của bạn sẽ cực kỳ nổi bật đấy.', 'Nhẫn', 100, '["data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,"]', '2026-04-16 14:00:37');
INSERT INTO `product_detail` (`id`, `productCode`, `name`, `price`, `description`, `category`, `stock`, `image_url`, `created_at`) VALUES (11, '614281', 'Nhẫn đôi bạc đính đá CZ All Of Love LILI_614281', '2521000', 'Hẳn là người ấy và bạn sẽ đều rất vui và hạnh phúc khi cùng sở hữu kỷ vật tình yêu rất đẹp và ý nghĩa này, mà nhất là khi nó lại có thể đi cùng các bạn qua thời gian. Nhẫn đôi bạc All Of Love được làm từ bạc S925 cao cấp, điểm nhấn bởi viên đá Cubic Zirconia sang trọng và được chế tác hết sức tỉ mỉ bởi những nghệ nhân lành nghề. Chúc cặp đôi luôn hạnh phúc và sánh bước bên nhau cùng kỷ vật này nhé !!', 'Nhẫn', 100, '["data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,"]', '2026-04-16 14:03:03');
INSERT INTO `product_detail` (`id`, `productCode`, `name`, `price`, `description`, `category`, `stock`, `image_url`, `created_at`) VALUES (12, '289467', 'Nhẫn bạc nữ đính đá CZ hình bông hoa đào LILI_289467', '3111000', 'Chiếc nhẫn bạc S925 đính đá Cubic Zirconia với thiết kế hình bông hoa đào thống nhất khoe trọn vẻ đẹp nữ tính, rạng rỡ của người đeo nên thường được phái mạnh sử dụng làm món quà bất ngờ và vô cùng ý nghĩa cho nàng như lời gửi gắm, truyền tải những tâm tư và tình cảm chân thành dành cho nàng.

