INSERT INTO `product_detail` (`id`, `productCode`, `name`, `price`, `description`, `category`, `stock`, `image_url`, `created_at`) VALUES (13, '349632', 'Nhẫn bạc nữ mạ vàng 18k đính đá CZ hình trái tim LILI_349632', '2689000', 'Chiếc nhẫn được làm từ bạc 925 mạ vàng 18k với điểm nhấn là viên đá Cubic Zirconia hình trái tim. Được lấy cảm hứng từ những trái tim lãng mạn, e thẹn và ngọt ngào. Những trái tim nho nhỏ đính những viên đá Cubic Zirconia nổi bật đeo ở ngón tay bạn như được nhắc nhở rằng mình vẫn đang được yêu thương dù có đang cô đơn thế nào đi nữa. Đây là cách ghi nhớ thông điệp tình yêu rất duyên dáng, ý nhị, mà vẫn rất tươi sáng và trẻ trung.

', 'Nhẫn', 99, '["data:image/jpeg;base64,","data:image/jpeg;base64,","data:image/jpeg;base64,","data:image/jpeg;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,"]', '2026-04-16 14:08:40');
INSERT INTO `product_detail` (`id`, `productCode`, `name`, `price`, `description`, `category`, `stock`, `image_url`, `created_at`) VALUES (14, '054884', 'Nhẫn cặp đôi bạc đính kim cương Moissanite Layla LILI_054884', '3124000', 'Cặp nhẫn được làm từ bạc S925 đính viên kim cương Moissanite 0,5 carat sở hữu vẻ đẹp vừa quý phái lại vừa hiện đại, mang hơi hướng của sự phóng khoáng, là món phụ kiện không thể thiếu đối với mỗi cô gái, chàng trai, rất phù hợp khi làm quà tặng, cầu hôn, đính hôn, nhẫn cưới,… Chiếc nhẫn là món trang sức với kiểu dáng, thiết kế, màu sắc tinh tế và là đại diện cho mỗi phong cách khác nhau giúp chàng và nàng tự tin xuống phố, hội họp bạn bè hay dự một buổi tiệc tùng nào đó.

', 'Nhẫn', 98, '["data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,"]', '2026-04-16 14:11:24');
INSERT INTO `product_detail` (`id`, `productCode`, `name`, `price`, `description`, `category`, `stock`, `image_url`, `created_at`) VALUES (15, '819229', 'Nhẫn đôi bạc free size đính đá CZ hiệp sĩ và công chúa LILI_819229', '2086000', 'Hẳn là người ấy và bạn sẽ đều rất vui và hạnh phúc khi cùng sở hữu kỷ vật tình yêu rất đẹp và ý nghĩa này, mà nhất là khi nó lại có thể đi cùng các bạn qua thời gian. Nhẫn đôi bạc hiệp sĩ và công chúa đính đá CZ LILI_819229 được làm từ bạc S925 cao cấp, điểm nhấn bởi viên đá Cubic Zirconia sang trọng và được chế tác hết sức tỉ mỉ bởi những nghệ nhân lành nghề. Chúc cặp đôi luôn hạnh phúc và sánh bước bên nhau cùng kỷ vật này nhé !!

', 'Nhẫn', 99, '["data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,"]', '2026-04-16 14:13:17');
INSERT INTO `product_detail` (`id`, `productCode`, `name`, `price`, `description`, `category`, `stock`, `image_url`, `created_at`) VALUES (16, '372838', 'Nhẫn bạc nữ mạ bạch kim đính đá CZ cỏ 4 lá LILI_372838', '1999000', 'Bạn sẽ thêm phần cá tính và có gu hơn với chiếc nhẫn nữ cỏ 4 lá may mắn này đó. Lá đầu tiên đại diện cho niềm tin, lá thứ hai là sự hy vọng, lá thứ ba đại diện cho tình yêu và lá thứ tư là sự may mắn. Chắc chắn, chiếc nhẫn xinh xắn này sẽ mang đến vẻ đẹp, sức hút tuyệt vời cho chủ nhân của nó.

', 'Nhẫn', 100, '["data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,"]', '2026-04-16 14:14:37');
INSERT INTO `product_detail` (`id`, `productCode`, `name`, `price`, `description`, `category`, `stock`, `image_url`, `created_at`) VALUES (17, '338466', 'Nhẫn bạc nữ đính kim cương Moissanite Griselda LILI_338466', '2323000', 'Sản phẩm được làm từ bạc S925 đính viên kim cương Moissanite cao cấp. Khoác lên mình thiết kế độc đáo đầy tinh tế, mang đến vẻ đẹp kiêu kỳ, cá tính và sự trẻ trung cho cô nàng sở hữu. Đây cũng là món quà ý nghĩa mà phái mạnh có thể dành cho phái đẹp như thể hiện sự nâng niu, trân trọng, và bảo vệ người phụ nữ mình yêu.', 'Nhẫn', 100, '["data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,"]', '2026-04-16 14:16:02');
INSERT INTO `product_detail` (`id`, `productCode`, `name`, `price`, `description`, `category`, `stock`, `image_url`, `created_at`) VALUES (18, '132741', 'Nhẫn bạc nữ đính pha lê Aurora cá xinh xắn LILI_132741', '2156000', 'Chiếc nhẫn được làm từ bạc S925 được đính viên pha lê Aurora hình chú cá xinh xắn. Một phong cách thiết kế tượng trưng cho sự nữ tính, thanh lịch. Chắc hẳn bạn cũng như bất cứ cô gái nào cũng muốn mình trở thành chủ nhân của một chiếc nhẫn đặc biệt này đấy!

', 'Nhẫn', 98, '["data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,"]', '2026-04-16 14:18:41');
