INSERT INTO `product_detail` (`id`, `productCode`, `name`, `price`, `description`, `category`, `stock`, `image_url`, `created_at`) VALUES (20, '054793', 'Nhẫn bạc nữ đính kim cương Moissanite hình ngôi sao 6 cánh Gianna LILI_054793', '1899000', 'Chiếc nhẫn được làm từ bạc S925 mạ vàng trắng, đính kim cương Moissanite 1 carat với thiết kế hình ngôi sao 6 cánh đan xen vào sự độc đáo là một chút dịu dàng, mang đến vẻ đẹp vừa nhẹ nhàng lại vừa năng động. Dù bạn kết hợp chiếc nhẫn xinh xắn này với trang phục nào đi nữa thì đây cũng là dấu ấn thật sự tuyệt vời cho bạn!

', 'Nhẫn', 100, '["data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,"]', '2026-04-16 14:22:07');
INSERT INTO `product_detail` (`id`, `productCode`, `name`, `price`, `description`, `category`, `stock`, `image_url`, `created_at`) VALUES (21, '499436', 'Nhẫn bạc nữ 1 hột đơn giản đính đá CZ Royal Miracle LILI_499436', '2999000', 'Chiếc nhẫn được chế tác từ bạc S925 cao cấp được đính kèm viên đá Cubic Zirconia cao cấp. Thiết kế là lựa chọn hoàn hảo cho bạn trong những trang phục dự tiệc trang trọng. Bạn có muốn cùng nó hóa trang thành nàng công chúa lộng lẫy không nào?

