INSERT INTO `product_detail` (`id`, `productCode`, `name`, `price`, `description`, `category`, `stock`, `image_url`, `created_at`) VALUES (22, '077267', 'Nhẫn bạc nam đính đá CZ Antonio LILI_077267', '1509000', 'Chiếc nhẫn được làm từ bạc S925 đính đá Cubic Zirconia mang đến sự cuốn hút toát lên vẻ sang chảnh và nổi bật cho bạn. Chắc chắn em nó sẽ là một trong những items xứng đáng nhất trong tủ trang sức của bạn đó!

