INSERT INTO `product_detail` (`id`, `productCode`, `name`, `price`, `description`, `category`, `stock`, `image_url`, `created_at`) VALUES (24, '791795', 'Nhẫn bạc nữ may mắn Lucky Day LILI_791795', '1145000', 'Chiếc nhẫn được làm từ bạc S925 cao cấp, mang thiết kế chữ Lucky ở trung tâm vô cùng thời trang và phong cách sẽ là sự lựa chọn hoàn hảo cho các cô gái cá tính, trẻ trung, phóng khoáng. Chiếc nhẫn may mắn này kết hợp với cá tính của bạn chắc chắn sẽ khiến bạn vô cùng đặc biệt đấy!

