INSERT INTO `product_detail` (`id`, `productCode`, `name`, `price`, `description`, `category`, `stock`, `image_url`, `created_at`) VALUES (33, '831944', 'Dây chuyền bạc nữ đính đá CZ cá tiên LILI_831944', '1333000', 'Bạn sẽ không chỉ thêm phần xinh xắn và thanh lịch khi diện em dây chuyền bạc với thiết kế cá tiên độc đáo này, mà còn thể hiện gu thẩm mỹ rất riêng đấy nhé. Hãy tưởng tượng bạn sẽ duyên dáng và thu hút làm sao khi bạn diện chiếc vòng cổ này đi làm, đi hẹn hò hay đi chơi với bạn bè. Em nó được làm từ bạc 925 chuyên dụng , điểm nhấn bởi những viên đá Cubic Zirconia cao cấp và được chế tác hết sức tỉ mỉ bởi những nghệ nhân lành nghề. Cùng em nó ra ngoài và tỏa sáng thôi nào !!

