INSERT INTO `product_detail` (`id`, `productCode`, `name`, `price`, `description`, `category`, `stock`, `image_url`, `created_at`) VALUES (34, '123985', 'Dây chuyền đôi bạc đính đá CZ hình cá voi và bướm Brenna LILI_123985', '2799000', 'Nếu bạn đang tìm kiếm một mẫu trang sức trang sức đẹp, tinh tế cho cặp đôi thì chiếc dây chuyền đôi bạc hình cá voi và bướm tình yêu này hoàn toàn thỏa mãn điều đó. Dây chuyền làm từ bạc đính đá Cubic Zirconia cao cấp với thiết kế hy vọng tình yêu đôi lứa sẽ luôn đẹp, mãi bền chặt, đi cùng nhau đến cuối con đường. Chúc các bạn hạnh phúc nhé !!

', 'Dây chuyền', 100, '["data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,"]', '2026-04-22 05:05:26');
INSERT INTO `product_detail` (`id`, `productCode`, `name`, `price`, `description`, `category`, `stock`, `image_url`, `created_at`) VALUES (35, '106179', 'Dây chuyền bạc đôi đính đá mã não rồng và phượng Walter LILI_106179', '2699000', 'Cặp dây chuyền được làm bằng bạc S925 đính đá mã não với thiết kế hình rồng và phượng mang đến cho bạn và người ấy sự trang nhã và thanh lịch. Hai bạn đã sẵn sàng để tỏa sáng và thu hút mọi ánh nhìn cùng em nó chưa nào !!

