INSERT INTO `product_detail` (`id`, `productCode`, `name`, `price`, `description`, `category`, `stock`, `image_url`, `created_at`) VALUES (36, '413898', 'Dây chuyền bạc nữ đính kim cương Moissanite tròn cách điệu LILI_413898', '1699000', 'Một thiết kế đầy sang trọng đến từ trang sức LiLi, hãy tưởng tượng thiết kế dây chuyền bạc hình tròn cách điệu xinh xắn này ở trên cổ bạn, khi đi làm, đi chơi hay hẹn hò, sẽ thật tuyệt vời phải không nào. Món trang sức bạc này sẽ giúp bạn thêm phần đáng yêu và thu hút đó. Em nó được làm từ bạc 92.5% nguyên chất đính kim cương Moissanite 1 carat cao cấp. Cùng em nó ra ngoài và tỏa sáng thôi nào !!

', 'Dây chuyền', 100, '["data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,"]', '2026-04-22 05:07:56');
INSERT INTO `product_detail` (`id`, `productCode`, `name`, `price`, `description`, `category`, `stock`, `image_url`, `created_at`) VALUES (37, '558997', 'Dây chuyền đôi bạc đính đá CZ gắn nam châm Heart to Heart LILI_558997', '2399000', 'Nếu bạn đang tìm kiếm một mẫu trang sức trang sức đẹp, tinh tế cho cặp đôi thì dây chuyền đôi bạc Heart to Heart LILI_558997 hoàn toàn thỏa mãn điều đó. Dây chuyền làm từ bạc đính đá Cubic Zirconia cao cấp, chia làm hai nửa trái tim của đôi trai gái, được gắn kết với nhau bằng cặp nam châm trái cực, với hy vọng tình yêu đôi lứa sẽ luôn đẹp, mãi bền chặt, đi cùng nhau đến cuối con đường. Chúc các bạn hạnh phúc nhé !!

