INSERT INTO `product_detail` (`id`, `productCode`, `name`, `price`, `description`, `category`, `stock`, `image_url`, `created_at`) VALUES (38, '426865', 'Dây chuyền bạc nữ đính đá CZ cỏ 4 lá LILI_426865', '1689000', 'Sản phẩm được làm từ bạc S999 với điểm nhấn là thiết kế hình cỏ 4 lá đính đá Cubic Zirconia cao cấp. Lá đầu tiên đại diện cho niềm tin, lá thứ hai là sự hy vọng, lá thứ ba đại diện cho tình yêu và lá thứ tư là sự may mắn. Điểm khác biệt so với các sản phẩm khác đó là ngôn ngữ thiết kế của sản phẩm được khai thác tinh tế hơn với vị trí xuất hiện đầy khéo léo. Chiếc dây chuyền xinh xắn này chắc chắn sẽ mang đến vẻ đẹp, sức hút tuyệt vời cho bạn đó!

